def transform(grid):
    rows, cols = len(grid), len(grid[0])
    grid_out = [row[:] for row in grid]

    for hr in range(rows):
        for hc in range(cols):
            if grid[hr][hc] == 5:
                neighbors = []
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        r, c = hr + dr, hc + dc
                        if 0 <= r < rows and 0 <= c < cols:
                            neighbors.append(grid[r][c])

                if neighbors and all(x == 9 for x in neighbors):
                    grid_out[hr][hc] = 4

    return grid_out
